    aiAgents: ["Leasing Agent", "Depot Operations Agent", "Equipment Agent", "Finance Agent"],
    handoffPoints: ["Lease approval triggers agreement", "On-hire triggers fleet tracking", "Off-hire triggers settlement"],
    typicalTimeline: "1-10 years lease period",
