    humanGates: ["Clearance holds (step 7)", "Port services (step 11)", "Cash to master (step 12)", "PDA variance approval (step 16)"],
    participatingModules: ["Port Intelligence", "Pre-Arrival", "Terminal", "Compliance", "Security", "Clearance", "Husbandry", "Cargo Ops", "Disbursement", "Performance", "Tariff"],
