        outputFields: ["Regulatory Reports Filed per Jurisdiction", "Filing Confirmations and Reference Numbers", "Filing Deadline Compliance Status", "SAR/STR Filed (if applicable)", "Regulatory Authority Correspondence"],
        dependencies: [{ ref: "step-5", type: "data", label: "Sanctions response executed" }],
