    humanGates: ["Severity assessment (step 2)", "Survey (steps 4-5)", "Liability decision (step 8)", "Negotiation (step 11)", "Settlement amount (step 12)", "GA declaration (step 17)"],
    participatingModules: ["Safety", "Claims", "Insurance", "Finance", "Emergency", "Risk", "Regulatory"],
